insert into public.mistakes (id, title, what_happened, lesson, category, cringe, visibility, author, created_at, base_reactions)
values
  ('seed-reply-all', 'Replied-all to 400 people with ''lol who invited Kevin''', 'Company-wide invite for the end-of-year party. Meant to send my snarky comment to one friend. Sent it to the entire company. Including Kevin. Kevin organised the party.', 'Check the To: field like it owes you money. Also, Kevin is lovely and I now help him plan every party.', 'work', 5, 'public', 'Priya', '2026-11-11T09:12:00.000Z', '{"been-there":248}'::jsonb),
  ('seed-dish-soap', 'Put washing-up liquid in the dishwasher', 'Ran out of dishwasher tablets, figured soap is soap. Twenty minutes later the kitchen looked like a foam party in Ibiza. The dog was thrilled.', 'The special detergent exists for a reason. Read the label before improvising.', 'food', 4, 'public', 'Marco', '2026-11-10T18:40:00.000Z', '{"been-there":131}'::jsonb),
  ('seed-wave', 'Waved back at someone who was waving at the person behind me', 'Big enthusiastic wave across a busy café. They walked straight past me into the arms of their actual friend.', 'Commit to the bit: turn it into a stretch, fix your hair, nobody will ever know. Everyone does this.', 'social', 3, 'public', '', '2026-11-09T12:05:00.000Z', '{"been-there":412}'::jsonb),
  ('seed-wrong-folder', 'Deleted the wrong folder. The important one.', 'Cleaning up my laptop at 1am. Confidently deleted "old_stuff". It was not old stuff. It was my entire thesis draft.', 'Backups aren''t boring, they''re love letters to future you. I now back up everything twice and sleep like a baby.', 'tech', 5, 'public', 'Jo', '2026-11-08T01:22:00.000Z', '{"been-there":189}'::jsonb),
  ('seed-love-you', 'Ended a call with my boss by saying ''love you, bye!''', 'Had just been on the phone to my mum. Autopilot took over. There was a long pause, then my boss said "...love you too?"', 'Autopilot is powerful. Slow down at the end of calls. On the bright side, team morale has never been higher.', 'work', 4, 'public', 'Dani', '2026-11-06T16:30:00.000Z', '{"been-there":356}'::jsonb),
  ('seed-cheap-flight', 'Booked a ''bargain'' flight to an airport 2 hours from the city', 'Saved £40 on the flight. Spent £70 on a coach and missed the first evening of the trip.', 'The cheapest option often has hidden costs. Check the map, not just the price.', 'travel', 2, 'public', 'Tom', '2026-11-04T07:45:00.000Z', '{"been-there":97}'::jsonb),
  ('seed-free-trials', 'Signed up for six free trials and forgot every single one', 'Was paying for three streaming services, a language app, a meal kit and a premium weather app. A premium. Weather. App.', 'Set a reminder the moment you sign up for anything "free".', 'money', 3, 'public', 'Aisha', '2026-11-02T20:10:00.000Z', '{"been-there":173}'::jsonb),
  ('seed-egg', 'Reheated a boiled egg in the microwave', 'It exploded the moment I bit into it. I can still hear the pop.', 'Eggs are tiny grenades. Some things are best eaten cold.', 'food', 4, 'public', 'Sam', '2026-10-30T13:00:00.000Z', '{"been-there":88}'::jsonb),
  ('seed-you-too', 'Said ''you too'' when the waiter said ''enjoy your meal''', 'He was not eating. He was working. We both pretended it did not happen.', 'Laughing it off is the right move. Nobody remembers it but you.', 'social', 2, 'public', '', '2026-10-27T19:20:00.000Z', '{"been-there":521}'::jsonb),
  ('seed-mute', 'Gave a whole presentation on mute', 'Practised for two weeks. Delivered it perfectly. Nine minutes in, someone typed "we can''t hear you" in the chat.', 'Always open with "can everyone hear me?" The boring check saves the day. My second run was even better.', 'work', 3, 'public', 'Leo', '2026-10-24T10:00:00.000Z', '{"been-there":204}'::jsonb),
  ('seed-paint', 'Painted the bedroom without checking the colour in daylight', 'Looked like a soft calming grey in the shop. In my room it is unmistakably the colour of an old swimming pool.', 'Test a patch first and look at it at different times of day. Or embrace the pool.', 'home', 2, 'public', 'Ngozi', '2026-10-20T15:15:00.000Z', '{"been-there":64}'::jsonb),
  ('seed-leg-day', 'Went from zero to a 10k run on day one', 'Bought new trainers, felt unstoppable, ran 10k with no training. Could not walk down stairs for four days. Went down them on my bum.', 'Start small and build up. Couch-to-5k exists for a reason, and the reason is stairs.', 'health', 3, 'public', 'Kofi', '2026-11-12T08:30:00.000Z', '{"been-there":142}'::jsonb),
  ('seed-wrong-exam', 'Revised for the wrong exam', 'Spent a week mastering statistics. Opened the paper. It was economics. The statistics exam was the following week.', 'Double-check the timetable, not just the date. On the plus side, I aced statistics the week after.', 'learning', 4, 'public', 'Mei', '2026-11-11T14:50:00.000Z', '{"been-there":117}'::jsonb),
  ('seed-pigeon', 'Tried to shoo a pigeon off my car and it moved into the sunroof', 'Left the sunroof open, waved my arms at the pigeon. It panicked in the only direction available: inside. We drove to work together.', 'Close things before you start flapping. Applies to pigeons and to life.', 'other', 2, 'public', '', '2026-11-10T07:15:00.000Z', '{"been-there":59}'::jsonb)
